"""Omnigent tool wrapper (generated by scripts/gen_tool_wrappers.py)."""

from omnigent_client.tools import tool

from injlab import tools_impl


@tool
def run_experiment(stack: str, attack: str, n: int, reason: str) -> str:
    """Run one experiment: n emails with the attack against the defense stack. Returns attack success rate with 95% CI and task score.

    Args:
        stack: Defense stack, e.g. 'D1+D2+D3'.
        attack: Approved attack family id, e.g. 'A3_encoded'.
        n: Number of samples (1-8 without extra approval).
        reason: One sentence: why the planner chose this test.
    """
    return tools_impl.run_experiment(stack, attack, n, reason)
